<?php $title='Edit story'; $active='stories'; require_once __DIR__ . '/_layout.php'; $pdo=db(); $id=(int)($_GET['id']??0); $s=['title'=>'','slug'=>'','artist_name'=>'','excerpt'=>'','body'=>'','featured_image'=>'','status'=>'draft']; if($id){$st=$pdo->prepare('SELECT * FROM stories WHERE id=?');$st->execute([$id]);$s=$st->fetch() ?: $s;} if($_SERVER['REQUEST_METHOD']==='POST'){ $img=upload_image($_FILES['featured_image']??[], 'stories') ?: ($s['featured_image']??null); $slug=$_POST['slug'] ?: slugify($_POST['title']); $pub=$_POST['status']==='published' ? date('Y-m-d H:i:s') : null; if($id){$st=$pdo->prepare('UPDATE stories SET title=?,slug=?,artist_name=?,excerpt=?,body=?,featured_image=?,status=?,published_at=? WHERE id=?');$st->execute([$_POST['title'],$slug,$_POST['artist_name'],$_POST['excerpt'],$_POST['body'],$img,$_POST['status'],$pub,$id]);} else {$st=$pdo->prepare('INSERT INTO stories(title,slug,artist_name,excerpt,body,featured_image,status,published_at) VALUES(?,?,?,?,?,?,?,?)');$st->execute([$_POST['title'],$slug,$_POST['artist_name'],$_POST['excerpt'],$_POST['body'],$img,$_POST['status'],$pub]);} redirect('stories.php'); } ?>
<h1><?= $id?'Edit':'Create' ?> story</h1><form method="post" enctype="multipart/form-data" class="panel"><div class="form-row"><label>Title</label><input name="title" required value="<?=h($s['title'])?>"></div><div class="form-row"><label>Slug</label><input name="slug" value="<?=h($s['slug'])?>"></div><div class="form-row"><label>Artist name</label><input name="artist_name" value="<?=h($s['artist_name'])?>"></div><div class="form-row"><label>Excerpt</label><textarea name="excerpt"><?=h($s['excerpt'])?></textarea></div><div class="form-row"><label>Body</label><textarea name="body" style="min-height:300px"><?=h($s['body'])?></textarea></div><div class="form-row"><label>Featured image</label><input type="file" name="featured_image" accept="image/*"><?php if($s['featured_image']): ?><p>Current: <?=h($s['featured_image'])?></p><?php endif; ?></div><div class="form-row"><label>Status</label><select name="status"><option <?=$s['status']==='draft'?'selected':''?>>draft</option><option <?=$s['status']==='published'?'selected':''?>>published</option></select></div><button class="btn">Save story</button></form><?php require __DIR__ . '/_footer.php'; ?>
